import { writeFileSync } from 'node:fs';
export default async function* report(source) {
 const files = new Map();
 for await (const event of source) {
  if (['test:pass','test:fail'].includes(event.type)) {
   const row = event.data;
   if (row.details?.type === 'test' && row.file) {
    const result = files.get(row.file) ?? {file:row.file,passed:0,failed:0,cases:[]};
    const status = event.type === 'test:pass' ? 'passed' : 'failed'; result[status]++;
    result.cases.push({name:row.name,status}); files.set(row.file,result);
   }
  }
 }
 writeFileSync('/tmp/cinashop-diy-commerce-toolchain-files.json', JSON.stringify([...files.values()],null,2)+'\n');
 yield 'Current source toolchain file inventory recorded\n';
}
